// Deploy to Heroku: the current commit plus the game content that's kept out of the public repo (assets/,
// src/data/swgr/, the welcome dialogue; all git-ignored, generated by tools/import_swgr.py). Builds a one-off commit
// on top of HEAD in a separate index, so the working tree and the branch are untouched, and force-pushes it to the
// heroku remote's main.
//   npm run ship
const { execFileSync } = require('node:child_process')
const fs = require('node:fs')
const path = require('node:path')

const ROOT = path.join(__dirname, '../..')
const CONTENT = ['assets', 'src/data/swgr', 'src/data/flavor/welcome.js']
const INDEX = path.join(ROOT, '.git', 'deploy-index')

const git = (args, env = {}) => execFileSync('git', args, { cwd: ROOT, env: { ...process.env, ...env }, encoding: 'utf8' }).trim()

for (const p of CONTENT) {
    if (!fs.existsSync(path.join(ROOT, p))) {
        console.error(`${p} is missing: run python tools/import_swgr.py first.`)
        process.exit(1)
    }
}
if (git(['status', '--porcelain', '--untracked-files=no'])) {
    console.error('Commit your changes first: the deploy is HEAD plus the game content.')
    process.exit(1)
}
try {
    const env = { GIT_INDEX_FILE: INDEX }
    git(['read-tree', 'HEAD'], env)
    git(['add', '--force', ...CONTENT], env)
    const tree = git(['write-tree'], env)
    const head = git(['rev-parse', '--short', 'HEAD'])
    const commit = git(['commit-tree', tree, '-p', 'HEAD', '-m', `Deploy ${head} with game content`])
    console.log(`Pushing ${head} + game content to Heroku...`)
    execFileSync('git', ['push', '--force', 'heroku', `${commit}:refs/heads/main`], { cwd: ROOT, stdio: 'inherit' })
} finally {
    fs.rmSync(INDEX, { force: true })
}
